CREATE DATABASE IF NOT EXISTS canteen_db; USE canteen_db;
CREATE TABLE menu_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,category VARCHAR(60) NOT NULL,price DECIMAL(10,2) NOT NULL,stock_qty INT NOT NULL DEFAULT 0,available BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE canteen_orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(100) NOT NULL,order_time DATETIME NOT NULL,total_amount DECIMAL(10,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PLACED');
CREATE TABLE order_lines(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,menu_item_id BIGINT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,line_total DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES canteen_orders(id),FOREIGN KEY(menu_item_id) REFERENCES menu_items(id));